        System.out.println(number + " entered.");

        scanner.close();
    }
}
```

#### 2. Handle End-of-File:
   - Always check for the end-of-input before proceeding further.

```java
import java.util.Scanner;

public class RetrieveInputExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        try {
            System.out.println("Enter an integer:");
            while (!scanner.hasNextInt()) {
                System.out.println("Invalid input. Please enter an integer.");
                scanner.nextLine(); // Clear invalid input
            }
            int number = scanner.nextInt();
            System.out.println(number + " entered.");
        } catch (InputMismatchException e) {
            System.err.println("Error: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}
```

#### 3. Validate User Input:
   - Add validation checks to ensure the input meets certain criteria.

```java
import java.util.Scanner;

public class RetrieveInputExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter an integer between 0 and 10: ");
        int number;
        do {
            if(scanner.hasNextInt() && (number = scanner.nextInt()) >= 0 && number <= 10) {
                System.out.println(number + " entered.");
                break;
            } else {
                System.out.println("Invalid input. Integer between 0 and 10 is required.");
                scanner.nextLine(); // Clear invalid input
            }
        } while (true);

        scanner.close();
